export function getClinicalSelectorOptions(label: string, options: Choice[], current: string): Choice[] {
  const clinicalOptions = clinicalSelectorOptions[label] ?? options;
  return clinicalOptions.some(([value]) => value === current) ? clinicalOptions : [[current, `Previously recorded: ${current}`], ...clinicalOptions];
}
